package main

import (
	"crypto/subtle"
	"encoding/base64"
	"strconv"
	"strings"
)

// Accounts maps a user name to its password.
type Accounts map[string]string

const basicScheme = "Basic "

type authPair struct {
	value string
	user  string
}

type authPairs []authPair

func (a authPairs) searchCredential(authValue string) (string, bool) {
	if authValue == "" {
		return "", false
	}
	provided := trimScheme(authValue)
	for _, pair := range a {
		if subtle.ConstantTimeCompare([]byte(trimScheme(pair.value)), []byte(provided)) == 1 {
			return pair.user, true
		}
	}
	return "", false
}

func trimScheme(v string) string {
	if i := strings.IndexByte(v, ' '); i >= 0 {
		return v[i+1:]
	}
	return v
}

func processAccounts(accounts Accounts) authPairs {
	length := len(accounts)
	if length == 0 {
		panic("Empty list of authorized credentials")
	}
	pairs := make(authPairs, 0, length)
	for user, password := range accounts {
		if user == "" {
			panic("User can not be empty")
		}
		pairs = append(pairs, authPair{
			value: authorizationHeader(user, password),
			user:  user,
		})
	}
	return pairs
}

func authorizationHeader(user, password string) string {
	base := user + ":" + password
	return basicScheme + base64.StdEncoding.EncodeToString([]byte(base))
}

func renderAuthenticateHeader(realm string) string {
	if realm == "" {
		realm = "Authorization Required"
	}
	return basicScheme + "realm=" + strconv.Quote(realm)
}

