package main

import (
    "fmt"
    "os"
    "encoding/base64"
)

func main() {
    pass, fail := 0, 0

    func() {
        defer func() {
            if r := recover(); r != nil {
                pass++
            } else {
                fail++
                fmt.Fprintln(os.Stderr, "empty accounts should panic")
            }
        }()
        processAccounts(Accounts{})
    }()

    func() {
        defer func() {
            if r := recover(); r != nil {
                pass++
            } else {
                fail++
                fmt.Fprintln(os.Stderr, "empty user should panic")
            }
        }()
        processAccounts(Accounts{"": "pw"})
    }()

    pairs := processAccounts(Accounts{"admin": "password", "user": "pass"})
    adminValue := "Basic " + base64.StdEncoding.EncodeToString([]byte("admin:password"))
    userValue := "Basic " + base64.StdEncoding.EncodeToString([]byte("user:pass"))

    if authorizationHeader("admin", "password") == adminValue {
        pass++
    } else {
        fail++
        fmt.Fprintln(os.Stderr, "authorizationHeader admin")
    }

    if u, ok := pairs.searchCredential(adminValue); ok && u == "admin" {
        pass++
    } else {
        fail++
        fmt.Fprintln(os.Stderr, "valid admin credential")
    }

    if u, ok := pairs.searchCredential(userValue); ok && u == "user" {
        pass++
    } else {
        fail++
        fmt.Fprintln(os.Stderr, "valid user credential")
    }

    if _, ok := pairs.searchCredential("Basic " + base64.StdEncoding.EncodeToString([]byte("admin:wrong"))); !ok {
        pass++
    } else {
        fail++
        fmt.Fprintln(os.Stderr, "wrong password accepted")
    }

    if _, ok := pairs.searchCredential(base64.StdEncoding.EncodeToString([]byte("admin:password"))); !ok {
        pass++
    } else {
        fail++
        fmt.Fprintln(os.Stderr, "missing scheme accepted")
    }

    if _, ok := pairs.searchCredential("Bearer " + base64.StdEncoding.EncodeToString([]byte("admin:password"))); !ok {
        pass++
    } else {
        fail++
        fmt.Fprintln(os.Stderr, "other scheme accepted")
    }

    if _, ok := pairs.searchCredential(""); !ok {
        pass++
    } else {
        fail++
        fmt.Fprintln(os.Stderr, "empty accepted")
    }

    if _, ok := pairs.searchCredential("Basic "); !ok {
        pass++
    } else {
        fail++
        fmt.Fprintln(os.Stderr, "empty basic accepted")
    }

    if renderAuthenticateHeader("") == `Basic realm="Authorization Required"` {
        pass++
    } else {
        fail++
        fmt.Fprintln(os.Stderr, "default realm")
    }

    if renderAuthenticateHeader("test") == `Basic realm="test"` {
        pass++
    } else {
        fail++
        fmt.Fprintln(os.Stderr, "custom realm")
    }

    fmt.Printf("TESTS %d %d\n", pass, fail)
    if fail > 0 {
        os.Exit(1)
    }
}
